/* Editorial English edition of the portfolio. No third-party translation service. */
window.PortfolioEN = (() => {

const schedulingIllustration=(kind,en=false)=>{
 const zh={
  continuity:['學生課程','主要老師','代課老師','主要老師','主要老師'],
  authority:['學生時段','課程間隔','老師分配','排課草案','老師檢查與調整'],
  changing:['初次排課','臨時請假','尋找代課／補課','更新課表'],
  adoption:['自動產生課表','新工具學習','異動維護','整體負擔待驗證'],
  collaboration:['學生','主要老師','代課老師','LINE 協作與通知']
 };
 const english={
  continuity:['Student lessons','Main teacher','Substitute','Main teacher','Main teacher'],
  authority:['Availability','Lesson spacing','Teacher assignment','Draft timetable','Instructor reviews and adjusts'],
  changing:['Initial plan','Absence','Find cover / make-up','Update schedule'],
  adoption:['Auto-generated plan','Tool onboarding','Change upkeep','Total effort unverified'],
  collaboration:['Student','Main instructor','Substitute','LINE communication']
 };
 const v=(en?english:zh)[kind];
 let inside='';
 if(kind==='continuity')inside='<div class="schedule-scene-label">'+v[0]+'</div><div class="schedule-scene-lessons">'+v.slice(1).map((t,i)=>'<div class="'+(i===1?'substitute':'')+'"><span>'+(i+1).toString().padStart(2,'0')+'</span><strong>'+t+'</strong></div>').join('')+'</div>';
 if(kind==='authority')inside='<div class="schedule-scene-constraints">'+v.slice(0,3).map(t=>'<span>'+t+'</span>').join('')+'</div><div class="schedule-scene-arrow">↓</div><div class="schedule-scene-draft">'+v[3]+'</div><div class="schedule-scene-arrow">↓</div><div class="schedule-scene-decision">'+v[4]+' ✓</div>';
 if(kind==='changing')inside='<div class="schedule-scene-stages">'+v.map((t,i)=>'<div class="'+(i===1?'changed':'')+'"><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+t+'</strong></div>').join('')+'</div>';
 if(kind==='adoption')inside='<div class="schedule-scene-work"><div><span>−</span><strong>'+v[0]+'</strong></div><div><span>+</span><strong>'+v[1]+'</strong></div><div><span>+</span><strong>'+v[2]+'</strong></div></div><div class="schedule-scene-decision">'+v[3]+'</div>';
 if(kind==='collaboration')inside='<div class="schedule-scene-people">'+v.slice(0,3).map((t,i)=>'<div><span class="person-avatar">'+['●','◆','●'][i]+'</span><strong>'+t+'</strong></div>').join('')+'</div><div class="schedule-scene-links">↕　↕　↕</div><div class="schedule-scene-decision">'+v[3]+'</div>';
 return '<div class="schedule-scene schedule-scene--'+kind+'" aria-hidden="true">'+inside+'</div>';
};
const schedulingInsight=(num,label,title,copy,kind,caption,en=false)=>'<article class="schedule-insight-card"><div class="schedule-insight-copy"><div class="schedule-insight-heading"><em>'+num+'</em><span>'+label+'</span></div><h4>'+title+'</h4><p>'+copy+'</p></div><figure class="schedule-insight-figure">'+schedulingIllustration(kind,en)+'<figcaption>'+caption+'</figcaption></figure></article>';

 const section=(id,n,label,title,body)=>`<section class="story-section" id="${id}"><div class="story-kicker">${n} / ${label}</div><h2>${title}</h2>${body}</section>`;
 const p=t=>`<p>${t}</p>`;
 const img=(file,alt,caption,cls='')=>`<figure class="${cls||'english-figure'}"><img loading="lazy" src="./${file}" alt="${alt}"><figcaption>${caption}</figcaption></figure>`;
 const evidence=(tag,title,copy)=>`<div class="english-evidence"><span>${tag}</span><h3>${title}</h3><p>${copy}</p></div>`;
 const two=(a,b)=>`<div class="english-pair">${a}${b}</div>`;
 const nav={scheduling:['Overview','Problem Discovery','Product Strategy','Design & Build','Reflection'],kiosk:['Overview','Research Approach','Product Decisions','Design & Validation','Outcome'],kds:['Context','Discovery','User Analysis','Product Decisions','Independent Design','Reflection']};
 const content={
 scheduling:()=>
 section('overview','01','PROJECT OVERVIEW','I built a working scheduling product—then learned to rethink what was worth building first',
  p('This independent project began with a Pilates instructor’s real challenge: building the monthly timetable takes approximately 2–3 hours, followed by frequent cancellations and changes. She collects availability in LINE, arranges classes on paper, and coordinates substitute teachers in a group chat. The challenge involves not only finding open slots but making trade-offs and managing ongoing coordination.')+
  '<div class="schedule-feature-quote"><span>INITIAL DESIGN QUESTION</span><p>Before building the first version, I framed the challenge as a design question:</p><strong>How might we respect each student’s availability, balance fairness and teaching continuity, and help the instructor plan an entire month efficiently?</strong></div>'+
  '<figure class="scenario-figure pilates-case-scenario"><img loading="eager" decoding="async" fetchpriority="high" width="2048" height="1536" src="./assets/pilates-scenario.webp" alt="Composite lifestyle scene of a Pilates instructor viewing the scheduling system on her phone"><figcaption>Use scenario (composite image).</figcaption></figure>')+
 section('research','02','PROBLEM DISCOVERY','The problem goes beyond scheduling time: balancing different constraints',
  '<div class="schedule-problem-grid">'+evidence('INSTRUCTOR / REPORTED','One-to-one coordination concentrates the work on the instructor','She must collect availability, balance lessons with the primary instructor, allow intervals between sessions, and coordinate substitutes. Initial planning takes 2–3 hours per month, with further cancellations and changes.')+evidence('STUDENTS / INSTRUCTOR REPORTED','First-come-first-served is not the preferred solution','The instructor previously tried student self-booking, but observed more cancellations and returned to instructor-led scheduling.')+'</div>'+
  '<h3>Initial assumptions before building | Source: one instructor</h3>'+
  schedulingInsight('01','TEACHING CONTINUITY','Scheduling quality depends not only on lesson counts, but on continuity with the primary instructor.','The instructor values regular lessons with the primary teacher. Allocation should preserve continuity rather than simply maximize the number of sessions.','continuity','Lesson pattern with a primary and a substitute teacher.',true)+
  schedulingInsight('02','DECISION AUTHORITY','Multiple constraints and exceptions resist full automation; the instructor must retain final authority.','Availability, lesson spacing, and instructor assignment can conflict. The system should propose a draft and surface conflicts for human review.','authority','Multiple constraints; the draft still needs the instructor’s review.',true)+
  schedulingInsight('03','CONTINUOUS COORDINATION','Scheduling is not a one-time allocation; absences, make-up lessons, and substitute needs keep it changing.','The first timetable is only a starting point. Later changes require renewed coordination and updated information across participants.','changing','Illustrative change sequence showing ongoing coordination.',true)+
  '<p class="schedule-insight-disclaimer">These three points were assumptions formed from conversations with one instructor before I started building. Section 05 revisits them.</p>'+'<div class="schedule-turn"><span>PRODUCT FRAMING / REFRAMING THE PROBLEM</span><p>The core problem is not “how do students book faster?” but <strong>“how do we fairly allocate lessons students can accept while giving the instructor flexibility to adjust the monthly timetable?”</strong></p></div>')+
 section('opportunity','03','PRODUCT STRATEGY','Automate scheduling rules while keeping instructors in control',
  p('Version one had to answer one question: <strong>who decides which student takes which lesson?</strong> I split it across three roles, in order, so each does only the part it is best at.')+
  '<div class="schedule-flow"><article><b class="sf-num">01</b><span>STUDENT</span><h3>Submit acceptable times—no racing for slots</h3><dl><div><dt>What</dt><dd>Students mark the days and times they can attend. Tuesday only means Tuesday only.</dd></div><div><dt>Why</dt><dd>The instructor had tried open self-booking and saw more cancellations. Availability is a constraint, not a race.</dd></div></dl><div class="schedule-days schedule-days--mini" aria-label="A student who only accepts Tuesday"><i>Mon</i><i class="picked">Tue ✓</i><i>Wed</i><i>Thu</i><i>Fri</i><i>Sat</i><i>Sun</i></div></article><article><b class="sf-num">02</b><span>SYSTEM</span><h3>Draft the whole month by rule</h3><dl><div><dt>What</dt><dd>Checks availability, remaining sessions, lesson spacing and conflicts to produce a monthly draft.</dd></div><div><dt>Why</dt><dd>These are the repetitive checks behind the instructor’s 2–3 hours each month—the part rules handle best.</dd></div></dl></article><article><b class="sf-num">03</b><span>INSTRUCTOR</span><h3>Handle exceptions, then publish</h3><dl><div><dt>What</dt><dd>Reviews the allocation, adjusts by hand, then confirms and shares it with students.</dd></div><div><dt>Why</dt><dd>Student relationships and primary-instructor balance need judgment that fixed rules cannot make.</dd></div></dl></article></div><p class="schedule-flow-note">This split is a design assumption based on one instructor’s workflow; whether it saves time—and whether she will use it—needs a real scheduling cycle to test (see 05).</p>')+
 section('highlights','04','DESIGN & BUILD','Design and build: turning scheduling rules into cross-role coordination','<p class="schedule-highlight-intro">These three designs turn an instructor\'s tacit scheduling judgment, role-specific information needs, and ongoing substitute coordination into usable interfaces. Screens below are from the first product version with demo data.</p>'+'<article class="hl-row hl-row--pil"><div class="hl-copy"><span class="solution-num">01 / FROM MENTAL MODEL TO SCHEDULING RULES</span><h3>Making the instructor’s scheduling judgments visible as rules</h3><dl><div><dt>PROBLEM</dt><dd>Beyond availability, scheduling must consider remaining lessons, spacing, instructor continuity, and conflicts. Previously, many tradeoffs lived in the instructor’s experience.</dd></div><div><dt>DESIGN</dt><dd>Break those judgments into editable criteria and priorities, such as covering each student\'s minimum lessons before filling remaining sessions.</dd></div><div><dt>INTERACTION</dt><dd>The instructor inspects rules, generates a draft, then reviews states such as incomplete, submitted, and shared before confirming.</dd></div></dl><p class="hl-skills">UX Research × Domain Modeling × Rule-based Product Design</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-p1.jpg?v=2"><source src="./assets/pilates-hl-p1.mp4?v=2" type="video/mp4"></video></div><figcaption>Start → auto-schedule → confirm and share, pick recipients in LINE, then it shows as shared</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><span class="solution-num">02 / SWITCHING BETWEEN STUDENT AND TEACHER VIEWS</span><h3>Zooming from one student to the whole instructor week</h3><dl><div><dt>PROBLEM</dt><dd>A student\'s calendar alone cannot reveal the instructor\'s full capacity; a whole-week calendar alone can obscure an individual student\'s constraints.</dd></div><div><dt>DESIGN</dt><dd>Provide student-month and instructor-week views over the same scheduling information, allowing reviews at both individual and system levels.</dd></div><div><dt>INTERACTION</dt><dd>Search for a student and check scheduled sessions and availability, then open the instructor\'s weekly overview to assess overall occupancy.</dd></div></dl><p class="hl-skills">Information Architecture × Interaction Design</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-p2.jpg?v=2"><source src="./assets/pilates-hl-p2.mp4?v=2" type="video/mp4"></video></div><figcaption>A student’s available times, then the instructor’s whole week</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><span class="solution-num">03 / SUBSTITUTE & FREED-SLOT COORDINATION</span><h3>From manually finding replacements to surfacing candidates</h3><dl><div><dt>PROBLEM</dt><dd>Absences and substitutes require renewed checks on who is available, what remains unassigned, and which teachers need coordinating.</dd></div><div><dt>DESIGN</dt><dd>Gather substitute needs into a searchable, shareable list and surface students who previously selected a newly freed time slot.</dd></div><div><dt>INTERACTION</dt><dd>Use the substitute overview and LINE sharing for cross-instructor coordination; after a slot opens, the instructor may choose an eligible student. This is not fully automated notification.</dd></div></dl><p class="hl-skills">Workflow Design × Service Coordination</p></div><figure class="hl-clip hl-clip--shots"><div class="hl-shot-pair"><img loading="lazy" src="./assets/pilates-design-03a.webp" alt="Substitute overview with LINE sharing"><img loading="lazy" src="./assets/pilates-design-03b.webp" alt="Freed-slot candidates"></div><figcaption>Substitute overview and freed-slot screens (screenshots)</figcaption></figure></article>'+'<p class="schedule-highlight-note">Source: first-version product screenshots; student names are test records.</p><div class="schedule-live-demo" id="try-demo"><div class="schedule-live-copy"><span>TRY THE PRODUCT / INTERACTIVE DEMO</span><h3>The production flow, without the LINE login</h3><p>This runs the production product’s code and flow with only the LINE login removed and sample data in its place: all 10 sample students have already submitted their times, so you can go straight to the key flow: start scheduling, review responses, run auto-scheduling, then use “confirm and share” next to a student to pick a LINE group or student in a simulated LINE share picker. Use the Instructor / Student switch above the phone to change views.</p><a href="./pilates-demo/teacher/" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese · LINE sharing is simulated and nothing is sent · Reload to reset the sample data</small></div><div class="schedule-live-stage"><div class="pil-view-switch" role="tablist" aria-label="切換視角"><button type="button" role="tab" data-pil-view="teacher" aria-selected="true">👩‍🏫 Instructor</button><button type="button" role="tab" data-pil-view="student" aria-selected="false">🙋‍♀️ Student</button></div><div class="schedule-live-frame"><iframe data-pil-frame="teacher" src="./pilates-demo/teacher/" title="Pilates scheduling instructor demo" loading="lazy"></iframe><iframe data-pil-frame="student" data-src="./pilates-demo/?t=t1" title="Pilates scheduling student demo" hidden></iframe></div></div></div>')+
 section('reflection','05','OUTCOME & REFLECTION','The turning point: the system worked, but the instructor would not adopt it',
  '<div class="schedule-adoption-turn"><span>THE TURNING POINT / FIRST INSTRUCTOR DEMO</span><h3>A workable timetable did not mean the instructor wanted a new workflow.</h3><p>I independently handled requirements, UI, rule design, and AI-assisted development. The first MVP could generate an editable timetable. Yet while the instructor saw potential value in the idea, she was not ready to adopt it for real scheduling. I had verified whether the system could allocate lessons—not whether it was worth switching to.</p></div>'+
  '<blockquote class="schedule-quote"><span>VERBATIM · THE INSTRUCTOR AFTER THE DEMO</span><p>“It honestly feels pretty good, but there are just so many variables. Am I supposed to teach every student one by one?”</p><small>Translated from Mandarin.</small></blockquote><div class="schedule-hypo-check"><span>HYPOTHESIS CHECK / REVISITING MY STARTING ASSUMPTIONS</span><h3>All three held; the one that failed was the assumption I never wrote down</h3><table><thead><tr><th>Assumption</th><th>After the demo</th><th>Evidence</th></tr></thead><tbody><tr><th scope="row"><span>01</span>Teaching continuity</th><td><em class="hc-ok">Held</em></td><td>She still wants students taught by their main instructor; substitutes are the exception.</td></tr><tr><th scope="row"><span>02</span>Instructor keeps the final say</th><td><em class="hc-ok">Held</em></td><td>“So many variables” shows rules cannot cover every exception; she still has to decide.</td></tr><tr><th scope="row"><span>03</span>Continuous coordination</th><td><em class="hc-up">Held — and underestimated</em></td><td>Version one mainly solved the first monthly plan; the everyday load is absences, make-ups and cover.</td></tr><tr><th scope="row"><span>Hidden</span>She mainly wants faster scheduling</th><td><em class="hc-no">Overturned</em></td><td>Her worry was not speed but teaching every student a new tool and who maintains the changes.</td></tr></tbody></table><p>The first three come from the initial assumptions in Section 02. What actually stalled the product was assuming that saving time was what she valued most—without checking.</p></div>'+
  '<div class="schedule-reframe schedule-reframe--turn"><span>PRODUCT REFRAMING / NEXT DIRECTION</span><h3>From maximizing automation to reducing adoption cost</h3><p>I chose to retain the scheduling rules and manual override while rethinking how availability and changes enter the workflow. The next concept uses LINE—already familiar to students and instructors—as the main touchpoint, reducing the need to learn and switch tools. Its bot flows and rules are <strong>planned, not implemented or validated through real adoption</strong>.</p></div>'+
  '<div class="schedule-next-check"><span>NEXT VALIDATION / NOT YET TESTED</span><h3>Validate willingness to use before claiming time saved</h3><p>Because the needs so far come from a single instructor, the next step is not building the LINE Bot first but checking with more instructors whether adoption and upkeep cost is a shared barrier. Only then should a real monthly cycle establish whether the instructor will keep using it, whether last-minute changes are easier, and whether scheduling time can fall from roughly 2–3 hours to one hour or less. Placing 40/40 simulated sessions cannot substitute for those outcomes.</p></div>'+
  '<div class="schedule-repo"><div><span>WORKING PRODUCT / SOURCE</span><strong>An interactive first version</strong><p>The first version’s implementation is available to inspect; the LINE Bot remains a planned direction.</p></div><a href="'+repoURL+'" target="_blank" rel="noopener">Explore GitHub ↗</a></div>'),



 kiosk:()=>
 section('overview','01','OVERVIEW','When KIOSK sales fell short, how could research inform the next product decisions?',
  p('The company had separate ordering and payment equipment and planned a next-generation integrated kiosk. Rather than transferring the old UI unchanged, the team needed to understand differences in restaurant menus, operational needs, and the relationship between onscreen prompts and physical payment hardware.')+
  ''+
  '<figure class="scenario-figure"><img src="./kiosk-scenario.png" alt="Conceptual integrated kiosk with display and payment hardware"><figcaption>Use scenario | how the screen relates to the physical payment hardware.</figcaption></figure>')+
 section('research','02','RESEARCH FRAMEWORK','Three research questions and the evidence behind them',
  '<div class="research-question-grid">'+
  '<div id="rq-1"><b class="rq-num">01</b><span>RQ 01 / PRODUCT FIT</span><strong>What functions and flows do different restaurant formats need?</strong><div class="rq-decision"><b>Method</b>Desk research + an exploratory scan of 40 stores across ~10 categories</div><div class="rq-value"><b>Where the answer is</b><a class="rq-link rq-link--wide" href="#kiosk-market">Market focus · priority store types <span aria-hidden="true">↓</span></a></div></div>'+
  '<div id="rq-2"><b class="rq-num">02</b><span>RQ 02 / COMPETITIVE GAP</span><strong>Which important capabilities are missing against competitors?</strong><div class="rq-decision"><b>Method</b>Competitive analysis of features, interfaces and flows</div><div class="rq-value"><b>Where the answer is</b><a class="rq-link" href="#kdec-1">Decision 01 · Add-on entry <span aria-hidden="true">↓</span></a></div></div>'+
  '<div id="rq-3"><b class="rq-num">03</b><span>RQ 03 / USER EXPERIENCE</span><strong>Where do merchants report operating difficulties and unmet needs?</strong><div class="rq-decision"><b>Method</b>Interviews with 7 store managers (no direct consumer interviews), plus earlier interview data</div><div class="rq-value"><b>Where the answer is</b><a class="rq-link" href="#kdec-2">Decision 02 · Payment guidance <span aria-hidden="true">↓</span></a><a class="rq-link" href="#kdec-3">Decision 03 · Item/set switching <span aria-hidden="true">↓</span></a></div></div></div>'+
  '<div class="kiosk-market-restored"><div class="kiosk-market-final" id="kiosk-market"><div class="kiosk-market-final-head"><span>MARKET FOCUS / TARGET FORMATS</span><h3>From a broad market to priority restaurant formats</h3><p>An exploratory scan of 40 stores across roughly ten formats helped identify restaurant types worth investigating further. The direction still needs validation with merchants.</p></div><div class="kiosk-market-final-main"><div class="market-conclusion"><div class="market-sizing market-sizing--circles"><div class="market-sizing-tam"><span>TAM</span><strong>Restaurants needing self-service ordering</strong><div class="market-sizing-sam"><span>SAM</span><strong>Formats current product could serve</strong><div class="market-sizing-focus"><span>TO VALIDATE</span><strong>Candidate formats</strong></div></div></div></div></div><div class="kiosk-market-screening"><span>SEGMENT CRITERIA / SCREENING HYPOTHESES</span><h4>What makes a merchant a better fit?</h4><p class="kiosk-screening-intro">Japanese specialty restaurants and beverage shops are examples worth exploring, not confirmed target segments. I used three business conditions to assess potential fit; the bar chart is not a priority ranking.</p><div class="kiosk-screening-item"><span>01 / TRANSACTION FREQUENCY</span><h5>High transaction frequency</h5><p>Concentrated peak-hour orders and a need to keep ordering quick.</p></div><div class="kiosk-screening-item"><span>02 / STANDARDIZATION</span><h5>Standardized ordering flow</h5><p>Relatively consistent menus and steps that self-service can support.</p></div><div class="kiosk-screening-item"><span>03 / AVERAGE ORDER VALUE</span><h5>Under NT$300</h5><p>An initial business screening threshold, not a fact about every target format.</p></div></div></div><div class="market-compare kiosk-market-final-stats"><div><span>40</span><strong>Stores</strong><small>Exploratory scan</small></div><div><span>10</span><strong>Formats</strong><small>Broad menu-based types</small></div><div><span>2</span><strong>Focus areas</strong><small>Japanese specialty / beverages</small></div></div><div class="evidence-details kiosk-market-final-chart is-open"><div class="market-chart"><div class="market-chart-head"><h6>Observed KIOSK adoption by format</h6><p>Higher bars show more observed brands, not greater product priority.</p></div><div class="market-bars"><div class="market-bar-row"><span>Chinese casual eateries</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:100%"></div></div><strong>7</strong></div><div class="market-bar-row"><span>Japanese specialty</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:100%"></div></div><strong>7</strong></div><div class="market-bar-row"><span>Fast food</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:86%"></div></div><strong>6</strong></div><div class="market-bar-row"><span>Beverage shops</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:86%"></div></div><strong>6</strong></div><div class="market-bar-row"><span>Western restaurants</span><div class="market-bar-track"><div class="market-bar " style="width:57%"></div></div><strong>4</strong></div><div class="market-bar-row"><span>Quick-service value meals</span><div class="market-bar-track"><div class="market-bar " style="width:43%"></div></div><strong>3</strong></div><div class="market-bar-row"><span>Noodle shops</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div><div class="market-bar-row"><span>Unmanned ramen</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div><div class="market-bar-row"><span>Cafés</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div><div class="market-bar-row"><span>Other</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div></div><p class="market-chart-note">The bar values count observed KIOSK-adopting brands by format, a different unit from the 40-store exploration; do not add them or generalize nationwide.</p></div></div></div></div>')+
 section('solutions','03','KEY PRODUCT DECISIONS','Three product decisions shaped by research',
 p('I compared merchant reports, earlier user research, and competitor patterns: competitors suggested add-on opportunities; managers reported difficulty finding physical payment modules; earlier interviews identified repetitive work when switching to a set. These three decisions distinguish supporting evidence from assumptions still needing validation.')+
 "<div class=\"kiosk-decision-intro\"><span>RESEARCH TO DESIGN / DESIGN DECISIONS</span><h3>Three core design decisions</h3><p>See how research informed <strong>add-on discovery, physical payment guidance, and switching between individual items and sets</strong>.</p></div><div class=\"research-question-grid kiosk-decision-rows\"><div id=\"kdec-1\"><b class=\"rq-num\">01</b><span>01 / COMMERCIAL OPPORTUNITY</span><strong>Make add-ons discoverable at the right moment<a class=\"rq-back\" href=\"#rq-2\">Answers RQ 02 ↑</a></strong><div class=\"rq-decision\"><b>Finding</b>71% of competitors offer an add-on entry, which points to an opportunity to offer complementary items, but direct consumer demand was not established.</div><div class=\"rq-value\"><b>Decision</b>Provide a clear add-on entry during selection; any effect on average order value still needs post-launch validation.<a class=\"dec-look\" href=\"#hl-addon\">See it in action <span aria-hidden=\"true\">↓</span></a></div></div><div id=\"kdec-2\"><b class=\"rq-num\">02</b><span>02 / SCREEN × HARDWARE</span><strong>Connect on-screen guidance to physical payment hardware<a class=\"rq-back\" href=\"#rq-3\">Answers RQ 03 ↑</a></strong><div class=\"rq-decision\"><b>Finding</b>Merchant managers described customers focusing on the screen and struggling to locate cash, card, or contactless payment modules.</div><div class=\"rq-value\"><b>Decision</b>Map payment instructions to the actual module locations to potentially reduce staff assistance.<a class=\"dec-look\" href=\"#hl-pay\">See it in action <span aria-hidden=\"true\">↓</span></a></div></div><div id=\"kdec-3\"><b class=\"rq-num\">03</b><span>03 / ORDER FLEXIBILITY</span><strong>Switch between items and sets without starting over<a class=\"rq-back\" href=\"#rq-3\">Answers RQ 03 ↑</a></strong><div class=\"rq-decision\"><b>Finding</b>Earlier interviews found that upgrading a single item to a set often required deleting it and repeating choices.</div><div class=\"rq-value\"><b>Decision</b>Let customers switch within the existing selection, reducing repetitive work and the risk of abandoning an order.<a class=\"dec-look\" href=\"#hl-combo\">See it in action <span aria-hidden=\"true\">↓</span></a></div></div></div><p class=\"kiosk-decision-status\">Adopted design direction; not a shipped or measured outcome</p><div class=\"kiosk-foundation-note\"><span>FOUNDATIONAL IMPROVEMENTS</span><p>Other adopted improvements addressed menu category navigation, invoice/carrier entry, returning to order editing before payment, first-use hints, fewer payment steps, and scanning/pickup feedback. They support the overall flow without requiring separate case studies here. Three additional directions remained unconfirmed or required further evaluation.</p></div>")+
 section('validation','04','DESIGN & VALIDATION','From design recommendations to early usability feedback',
  '<div class="design-phase design-phase--proposal"><div class="phase-banner"><span>PHASE 01 / DESIGN PROPOSALS</span><strong>Translate evidence into screens</strong><p>Each design is explained in turn, with a clip recorded from the live demo on the right; at the end you can try the whole flow yourself.</p></div><article class="hl-row" id="hl-pay"><div class="hl-copy"><span class="solution-num">01 / MY PROPOSAL · ADOPTED BY THE PM</span><h3>Guide people to the physical payment module</h3><p>Abstract cash or card icons cannot show where the machine accepts payment. I proposed an illustration of the whole device with the relevant slot highlighted, so people can map the screen to the hardware.</p><p>I ranked it first because it was the only problem that sat in the main flow, interrupted the transaction, and pulled staff away—fixing it reduces both customer friction and store support cost.</p><div class="state-note">Contribution: I proposed the guidance based on merchant reports and UI analysis; the PM accepted it for prototyping. In the prototype test, payment was the part participants found smoothest.</div></div><figure class="hl-clip ba ba--pay" data-ba><div class="ba-seg"><button type="button" data-v="before" class="on">BEFORE<i></i></button><button type="button" data-v="after">AFTER<i></i></button><span class="ba-hint">Switching automatically — tap to pause</span></div><div class="ba-stage"><div class="ba-pane" data-p="before"><div class="hl-clip-frame ba-still"><img src="./kiosk-payment-before.png" alt=""></div></div><div class="ba-pane" data-p="after" hidden><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-pay.jpg?v=1"><source src="./assets/kiosk-hl-pay.mp4?v=1" type="video/mp4"></video></div></div></div><figcaption class="ba-cap" data-p="before">Before: the screen only described the action, not where the module is.</figcaption><figcaption class="ba-cap" data-p="after" hidden>After: the camera moves to the coin slot, then the note acceptor</figcaption></figure></article><article class="hl-row" id="hl-combo"><div class="hl-copy"><span class="solution-num">02 / HISTORICAL RESEARCH REVIEW</span><h3>Switch between a single item and a meal set</h3><p>Earlier research found the existing system treated single items and sets as separate products, so changing your mind meant deleting and choosing again.</p><p>The redesign adds a one-tap upgrade/revert on the same product page, with sides adjusted on the same screen.</p><div class="state-note">Contribution: a team-generated direction that I helped assess and design.</div></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-combo.jpg?v=1"><source src="./assets/kiosk-hl-combo.mp4?v=1" type="video/mp4"></video></div><figcaption>Upgrading to a set and adjusting sides on the product page</figcaption></figure></article><article class="hl-row" id="hl-addon"><div class="hl-copy"><span class="solution-num">03 / ADOPTED DIRECTION</span><h3>Add-on purchase screen</h3><p>A separate add-on screen before checkout presents item photos, prices, and quantity controls.</p><p>A clear “No thanks” keeps upselling from becoming a barrier. It corresponds to the adopted “add-on purchase” recommendation.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-addon.jpg?v=1"><source src="./assets/kiosk-hl-addon.mp4?v=1" type="video/mp4"></video></div><figcaption>The add-on screen appears before payment; add items or skip</figcaption></figure></article><div class="kiosk-live-demo" id="try-demo"><div class="kiosk-live-copy"><span>TRY THE PROTOTYPE / FREE PLAY</span><h3>Walk through the redesigned ordering flow</h3><p>A working demo rebuilt from the Figma prototype: attract screen, dine-in or takeaway with table selection, ordering and set upgrades, add-ons, invoice options, and payment guidance animations matched to the kiosk hardware. Menu items, prices, and photos are sample data; payments are simulated; some details were added for the demo.</p><a href="./kiosk-demo/index.html?v=20261029" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese · Not connected to a live system · Use the 展示用 (demo) buttons to simulate payment</small></div><div class="kiosk-live-frame"><iframe src="./kiosk-demo/index.html?v=20261029" title="Self-ordering kiosk interactive demo" loading="lazy"></iframe></div></div></div>'+
 '<div class="design-phase design-phase--testing"><div class="phase-banner"><span>PHASE 02 / PROTOTYPE TESTING</span><strong>Find comprehension gaps by observing tasks</strong><p>Six internal colleagues participated in the first usability test.</p></div><h3>Payment felt smooth; set-meal options were less clear</h3><p>The internal prototype test checked early understanding, not live customer performance.</p><figure class="design-shot test-session-photo"><img src="./kiosk-prototype-test.png" alt="Six internal colleagues testing a kiosk prototype"><figcaption>Prototype sessions on the kiosk hardware.</figcaption></figure>'+
  '<div class="test-finding-grid"><div class="test-finding-positive"><div class="test-finding-label"><b class="test-finding-mark" aria-hidden="true">✓</b><span>POSITIVE SIGNAL</span></div><h4>Payment was relatively smooth</h4><p>Participants generally reported payment as one of the easiest task segments—a tentative signal supporting the flow.</p></div><div class="test-finding-negative"><div class="test-finding-label"><b class="test-finding-mark" aria-hidden="true">✕</b><span>USABILITY ISSUE</span></div><h4>Uniform square buttons obscured their purpose</h4><p>Some testers were unsure what they were expected to configure after opening a set-meal option.</p></div></div></div>'+
  '<div class="design-phase design-phase--iteration"><div class="phase-banner"><span>PHASE 03 / SECOND ITERATION</span><strong>Test feedback led to new layouts</strong><p>Four presentation patterns replaced a one-size-fits-all square button.</p></div><div class="solution"><span class="solution-num">04 / SECOND DESIGN ITERATION</span><h3>Four layouts for different amounts and types of information</h3><p>Based on the first prototype’s comprehension issues, we stopped using one square button for everything and chose layouts with two questions: <strong>does the customer need a picture to decide, and do they need to change quantity?</strong> That produced four patterns and a consistent rule merchants can follow when setting up new menus.</p>'+
  "<div class=\"layout-variants layout-variants--integrated\"><figure><div class=\"layout-variant-rationale\"><span>01 / Text choices</span><h4>Choosing a level without needing an image</h4><p>For rice portions, sweetness, ice, or other text-recognizable adjustments.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-compact.png\" alt=\"Text-only rice portion options\"></figure><figure><div class=\"layout-variant-rationale\"><span>02 / Horizontal cards</span><h4>Reading item details before deciding</h4><p>For sides or add-ons that need a name, price, and description.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-wide.png\" alt=\"Horizontal item cards with descriptions\"></figure><figure><div class=\"layout-variant-rationale\"><span>03 / Compact rows</span><h4>Selecting several items and changing quantity</h4><p>For extra sides or sauces with quick quantity controls.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-row.png\" alt=\"Compact rows with quantity controls\"></figure><figure><div class=\"layout-variant-rationale\"><span>04 / Large image cards</span><h4>Recognizing the option visually</h4><p>For set-meal sides or combinations where the image informs the choice.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-tile.png\" alt=\"Large cards emphasizing item photos\"></figure></div>"+
 '<div class="state-note">Iteration status: the project ended after the second design round, without retesting.</div></div></div>')+
 section('reflection','05','OUTCOME & REFLECTION','Outcomes, lessons, and what comes next',
 '<div class="kiosk-reflection-section kiosk-reflection-outcome"><span class="overline">01 / OUTCOME · PRODUCT DECISIONS</span><h3>How research changed the decisions</h3><p>I reframed disappointing kiosk sales around merchants’ expectations of product completeness and the staff effort created when customers get stuck. Of 12 recommendations, nine were adopted as design directions. I also independently proposed aligning on-screen payment guidance with physical hardware, and the PM approved it for prototyping. These are <strong>supported design decisions</strong>, not proof of shipping or measured impact.</p></div>'+
 '<div class="kiosk-reflection-section kiosk-reflection-learning"><span class="overline">02 / LEARNING · EVIDENCE LIMITS</span><h3>Different evidence answers different questions</h3><p>Competitor prevalence indicates market expectations but does not prove user demand. Reports from seven merchant managers and an exploratory scan of 40 stores offer useful clues, but require direct observation of customers. A prototype test with six internal colleagues revealed interface friction, while the second set-selection iteration remained untested; neither establishes real-world store performance.</p></div>'+
 '<div class="kiosk-reflection-section kiosk-reflection-next"><span class="overline">03 / NEXT STEPS · VALIDATION</span><h3>From adopted decisions to demonstrated value</h3><ul><li>Observe real customers paying and asking staff for help in stores.</li><li>Test the second set-selection layouts with target customers to assess errors, hesitation, and switching.</li><li>If launched, track payment help requests, ordering completion and task time, plus add-on usage and average order value.</li></ul></div>'),
 kds:()=>
 section('overview','01','CONTEXT','From an engineering demo to a deliverable KDS: first understand what kitchens need',
  ''+
  '<p>A customer expressed interest in buying a kitchen display system, so the company decided to turn an early demo—built by an engineer based on their own understanding—into a formal product. The prototype could show and process orders, but <strong>long dish names were truncated, scrolling text was hard to read, accidentally completed orders were difficult to recover, and oily hands made touch interaction cumbersome.</strong> The team first needed to clarify the initial scope and real kitchen workflows to turn the demo into a deliverable product.</p>'+
  '<figure class="scenario-figure kds-case-scenario"><img loading="lazy" src="./kds-case-hero.png" alt="Illustration of a cook using a kitchen display system"><figcaption>Kitchen use scenario.</figcaption></figure>')+
 section('research','02','DISCOVERY','How could we make evidence-based KDS decisions with a limited sample?',
  '<p>I triangulated <strong>feedback on the first-generation system, historical research, competitor comparisons, and contextual observation</strong> to understand preparation work and feature needs. LA PASTA was the only restaurant available for on-site research, so field data mainly adds working context.</p>'+
  '<p class="kds-research-method-summary"><strong>Evidence sources:</strong> first-generation feedback and UX audit, historical interviews and kitchen tickets, competitor analysis, and the LA PASTA field visit. This limited field sample provides context rather than a universal workflow.</p>'+
  '<div class="kds-competitor-analysis"><h3>Competitive Analysis</h3><p>Using the <strong>Protech first-generation KDS</strong> as our baseline, I compared <strong>Eats365</strong> and <strong>Weiby</strong> across order grouping, sorting, legibility, change notifications, and serving status. The goal was to identify missing essentials and viable patterns—not simply copy the longest feature list.</p>'+
  '<div class="kds-research-turn"><strong>Key takeaway:</strong> a KDS helps the kitchen make fast decisions about <strong>grouping, sequencing, and recognition</strong> under pressure, while ensuring significant changes and serving states are noticed.</div>'+
  '<div class="kds-competitor-findings">'+
  '<article><span>01 / GROUPING</span><h4>Group information by the unit of work</h4><p>Orders are often arranged by order or table. Eats365 also offers category grouping and an aggregate view, helping cooks focus on batches of similar dishes. A grouping mode corresponds to a different working unit.</p></article>'+
  '<article><span>02 / SORTING</span><h4>Balance preparation efficiency with waiting fairness</h4><p>Sorting may use order number, table, order time, or elapsed wait. Eats365 supports menu-based order; Weiby offers pickup-time sorting and pre-order handling to inform when preparation should begin.</p></article>'+
  '<article><span>03 / READABILITY</span><h4>Stable legibility matters more than configurability</h4><p>In the old Protech UI, certain field and text-size settings truncated long item names. Eats365 offers an alternate tradeoff: a more fixed layout with default views to preserve readable, complete information.</p></article>'+
  '<article><span>04 / ALERTS & STATUS</span><h4>Changes and serving status must travel beyond a static screen</h4><p>Eats365 uses sound for cancellations and marks changed order details, reducing repeated comparison work. Both competitors support preparation progress; Weiby extends certain states into the ordering flow.</p></article></div>'+
  '<a class="kds-compare-button" href="./kds-function-comparison.webp" target="_blank" rel="noopener noreferrer" aria-label="Open complete KDS feature comparison">View full competitor feature comparison <span aria-hidden="true">↗</span></a></div>')+
 section('user-analysis','03','USER ANALYSIS','How do kitchens batch dishes, notice changes, and determine serving order?',
  '<p>I formed an initial picture from <strong>historical tickets and requirements</strong>, then interviewed <strong>two front- and back-of-house participants at LA PASTA</strong> during one contextual site visit. The three insights below synthesize these different evidence sources.</p>'+
  '<div class="kds-user-metrics"><div><strong>Historical evidence</strong><span>Kitchen tickets and prior needs</span></div><div><strong>2 people</strong><span>LA PASTA front/back of house</span></div><div><strong>1 visit</strong><span>Contextual field study</span></div></div>'+
  '<h3>Interviews & Field Study</h3><div class="kds-field-site"><img loading="lazy" src="./la-pasta-logo.svg" alt="LA PASTA restaurant logo"><div><span>FIELD STUDY / RESEARCH SITE</span><strong>LA PASTA</strong><p>Our sole on-site interview and observation location.</p></div></div>'+
  '<h3>Three Key Insights</h3><div class="kds-user-insights">'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">01</em><span>BATCH PREPARATION</span></span><h4>Kitchen staff batch dishes with the same preparation process instead of finishing one order at a time</h4><p>Cooks check quantities of similar items across orders before collecting ingredients and preparing them together. Where refrigerators and cooking stations are apart, gathering ingredients in a batch reduces back-and-forth movement. The kitchen’s unit of work may be a batch of dishes, not an entire ticket.</p></div><figure class="kds-insight-figure"><div class="kds-mini-flow"><div><small>Order 01</small><strong>Dish A × 2</strong></div><div><small>Order 02</small><strong>Dish A × 1</strong></div><span class="kds-mini-arrow">↓</span><div class="kds-mini-highlight"><small>Combined preparation</small><strong>Dish A × 3</strong></div></div><figcaption>Batching logic.</figcaption></figure></article>'+
  '<figure class="kds-insight-context voice-paraphrase"><span>WORKING CONTEXT / FROM RESEARCH NOTES</span><p class="voice-text">With the refrigerator some distance from the cooking area, cooks check total demand for similar dishes and collect ingredients in one trip.</p></figure>'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">02</em><span>INTERRUPTED ATTENTION</span></span><h4>Cooks glance at the screen intermittently; significant changes cannot rely on silent updates</h4><p>Attention stays primarily on ingredients and cooking, not the KDS. Cancellations or edits that require repeatedly checking the display risk going unnoticed. Food residue and oily hands also make frequent touch interactions inconvenient.</p></div><figure class="kds-insight-figure"><div class="kds-attention-flow"><div><b>Preparing</b><span>Focus on food</span></div><div class="kds-attention-alert"><b>Order change</b><span>Must be noticed</span></div><div><b>Look back</b><span>Adjust the task</span></div></div><figcaption>Intermittent attention sequence.</figcaption></figure></article>'+
  '<figure class="kds-insight-context voice-paraphrase"><span>WORKING CONTEXT / FROM CUSTOMER FEEDBACK</span><p class="voice-text">Kitchen staff cannot watch the screen all the time. An audible cancellation or edit alert could help them react in time.</p></figure>'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">03</em><span>EFFICIENCY & FAIRNESS</span></span><h4>Serving sequence must consider both production efficiency and customers’ waiting time</h4><p>Combining similar dishes speeds preparation, but does not mean all identical items belong in one endless batch. Orders placed far apart in time need to remain distinguishable; a total item count alone obscures who has waited longer.</p></div><figure class="kds-insight-figure"><div class="kds-time-flow"><div><small>Earlier order</small><strong>12:00</strong><span>Dish A</span></div><div><small>Next order</small><strong>12:03</strong><span>Dish A</span></div><div class="kds-time-later"><small>Later order</small><strong>12:18</strong><span>Dish A</span></div></div><figcaption>Example order times.</figcaption></figure></article></div>'+
  '')+
 section('opportunity','04','PRODUCT DECISIONS','Team project | Translating research into actionable next-version directions',
  '<p>The first-phase MVP focuses on <strong>understanding preparation information, recovering from mistakes, and batching dishes</strong>. Existing feedback and competitor research informed directions for legibility, change alerts, order recovery, synchronized views, and fewer touch actions. These recommendations entered planning, and the product is in development and preparing for customer handoff. <strong>Another UX designer owns the main production UI. My role was research, scope discussion, and five UI review recommendations.</strong></p>'+
  '<h3>From insights to MVP delivery scope</h3><p>I grouped needs into three challenges: <strong>recognize information and prevent errors, support batched preparation, and make critical changes noticeable</strong>. With first-phase engineering constraints, the team narrowed the MVP to two delivery goals; later needs remain candidates, not commitments.</p>'+
  "<div class=\"kds-scope-heading\"><div><span>PHASED DELIVERY</span><h3>Nested circles show phased delivery goals</h3><p>Closer to the center means planned earlier, <strong>not more important</strong>. Only the center represents the current MVP scope; the other layers are possible future directions.</p></div></div>"+
  "<div class=\"kds-scope-layout\"><div class=\"kds-scope-rings\" role=\"img\" aria-label=\"Three bottom-aligned nested circles: MVP in the center, later store-level rules in the middle, and network resilience on the outside.\"><div class=\"kds-scope-outer\"><span>03 / FUTURE</span><strong>Network resilience</strong></div><div class=\"kds-scope-middle\"><span>02 / LATER</span><strong>Store-specific preparation rules</strong></div><div class=\"kds-scope-center\"><span>01 / THIS MVP</span><strong>Readable preparation data<br>and error recovery</strong><strong>Batch preparation</strong></div></div><div class=\"kds-scope-legend\"><div><span class=\"kds-scope-dot kds-scope-dot--now\"></span><div><small>01 / First delivery MVP</small><strong>Core preparation tasks</strong><p>Prioritize clear information, safer actions, and batch preparation. This is <strong>planned scope</strong>, not a shipped feature set.</p></div></div><div><span class=\"kds-scope-dot kds-scope-dot--later\"></span><div><small>02 / Later workflow management</small><strong>Rules reflecting store practices</strong><p>Explore per-item batch limits (e.g. three servings) and splitting batches by order-time difference (e.g. ten minutes). These are examples, not confirmed default rules or MVP commitments.</p></div></div><div><span class=\"kds-scope-dot kds-scope-dot--future\"></span><div><small>03 / Future resilience</small><strong>Handling network interruptions</strong><p>A longer-term direction outside the current MVP.</p></div></div></div></div>"+
  "<p class=\"kds-decision-bridge\">The evidence pointed to information legibility, error recovery, and batch preparation as core needs. The five UI review recommendations below were adopted by the team, but their post-launch impact has not been measured.</p>"+
  "<div class=\"kds-proactive-story\"><span>PROACTIVE DESIGN REVIEW</span><h3>When the UI drifted from real kitchen needs, I initiated a revision</h3><p>During the project I noticed that parts of the initial screen hierarchy and interaction patterns did not sufficiently reflect the research: kitchen staff need to scan information quickly and recognize critical states. I proactively reviewed the screens, proposed five specific improvements, and discussed the revisions with the UX designer responsible for the production UI.</p><p><strong>Outcome:</strong> The team adopted all five recommendations, and the production UI owner updated the design. This is a design revision outcome, not measured post-launch impact.</p></div>"+
  "<div class=\"ba ba--kds\" data-ba><div class=\"ba-main\"><div class=\"ba-seg\"><button type=\"button\" data-v=\"before\" class=\"on\">BEFORE<i></i></button><button type=\"button\" data-v=\"after\">AFTER<i></i></button><span class=\"ba-hint\">Switching automatically — tap to pause</span></div><div class=\"ba-stage\"><div class=\"ba-pane\" data-p=\"before\"><a class=\"kds-map-img\" href=\"./kds-ui-before.png\" target=\"_blank\" rel=\"noopener noreferrer\"><img loading=\"lazy\" src=\"./kds-ui-before.png\" alt=\"Previous white KDS interface with five issues marked\"><i class=\"kds-box\" data-n=\"1\" style=\"left:18.83%;top:1.38%;width:31.57%;height:5.66%\"><b>1</b></i><i class=\"kds-box kds-box--side\" data-n=\"2\" style=\"left:23.82%;top:22.95%;width:8.32%;height:5.20%\"><b>2</b></i><i class=\"kds-box\" data-n=\"2\" style=\"left:1.15%;top:95.79%;width:37.89%;height:3.83%\"></i><i class=\"kds-box\" data-n=\"3\" style=\"left:34.79%;top:29.30%;width:30.31%;height:11.63%\"><b>3</b></i><i class=\"kds-box\" data-n=\"3\" style=\"left:2.30%;top:51.72%;width:29.39%;height:5.66%\"></i><i class=\"kds-box\" data-n=\"4\" style=\"left:1.26%;top:13.93%;width:32.49%;height:6.12%\"><b>4</b></i><i class=\"kds-box\" data-n=\"4\" style=\"left:0.00%;top:8.57%;width:100.00%;height:4.59%\"></i><i class=\"kds-box\" data-n=\"5\" style=\"left:2.18%;top:34.81%;width:30.08%;height:16.22%\"><b>5</b></i></a></div><div class=\"ba-pane\" data-p=\"after\" hidden><a class=\"kds-map-img\" href=\"./kds-ui-after.png?v=6\" target=\"_blank\" rel=\"noopener noreferrer\"><img loading=\"lazy\" src=\"./kds-ui-after.png?v=6\" alt=\"Revised dark KDS interface\"></a></div><button type=\"button\" class=\"ba-peek\"><img src=\"./kds-ui-after.png?v=6\" alt=\"\"><span>See the fix →</span></button></div></div><ol class=\"ba-list kds-map-list\"><li data-n=\"1\"><b aria-hidden=\"true\">1</b><div><span>01 / SPACE ALLOCATION</span><strong>Reduce the station selector's footprint</strong><p>Station settings change infrequently but occupy prominent screen space.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"2\"><b aria-hidden=\"true\">2</b><div><span>02 / WAITING TIME</span><strong>Simplify waiting-time colors</strong><p>Use fewer signals to support faster interpretation.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"3\"><b aria-hidden=\"true\">3</b><div><span>03 / VISUAL PRIORITY</span><strong>Reserve warning colors for real alerts</strong><p>Frequent red and orange elements compete with critical information.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"4\"><b aria-hidden=\"true\">4</b><div><span>04 / INFORMATION DENSITY</span><strong>Reassess redundant details</strong><p>Revisit pending counts, area counts, and icons that repeat labels.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"5\"><b aria-hidden=\"true\">5</b><div><span>05 / NOTE USABILITY</span><strong>Prioritize note usability</strong><p>Low-frequency notes still need to be readable and actionable.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li></ol></div>")+
 section('solutions','05','INDEPENDENT EXPLORATION','Personal extension | Beyond the MVP: an item view that matches preparation rhythm',
  '<p>Outside the formal company scope, I examined a distinction: <strong>front-of-house teams track completed orders, while cooks may work by item and preparation process.</strong> Aggregating every identical item without limits, however, can hide order timing and exceed what the kitchen can make in one batch.</p>'+
  '<article class="hl-row hl-row--kds"><div class="hl-copy"><span class="solution-num">01 / ORDER ↔ ITEM VIEW</span><h3>Switch between order and item views</h3><p>Front of house tracks orders, but cooks often work by item. The order view tracks each ticket; the category and item views total the same dish across orders so it can be made in one batch, while every portion keeps its original order number.</p><p>Cooks check items first and then send them with Batch complete, so one mis-tap never clears a whole batch.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kds-hl-views.jpg?v=3" aria-label="Recording of switching between order, category and item views"><source src="./assets/kds-hl-views.mp4?v=3" type="video/mp4"></video></div><figcaption>Check and send in the order view, then switch to category and item views</figcaption></figure></article><article class="hl-row hl-row--kds"><div class="hl-copy"><span class="solution-num">02 / INFORMATION AWARENESS</span><h3>Keep a visible trace of important changes</h3><p>Cooks glance at the screen between tasks. An item cancelled at the counter does not vanish: it stays in place, highlighted and struck through, until a cook acknowledges it—so a dish already in progress never disappears without notice.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kds-hl-alert.jpg?v=3" aria-label="Recording of a cancelled item being acknowledged"><source src="./assets/kds-hl-alert.mp4?v=3" type="video/mp4"></video></div><figcaption>The cancelled item stays until it is acknowledged</figcaption></figure></article><article class="hl-row hl-row--kds"><div class="hl-copy"><span class="solution-num">03 / ERROR RECOVERY</span><h3>Recover accidentally completed items and resume preparation</h3><p>Mistakes happen under pressure. A fully checked order moves to Served automatically; if that was a mis-tap, the whole order can be restored or a single item sent back. Recovered items return in blue so cooks know they just came back.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kds-hl-recover.jpg?v=3" aria-label="Recording of restoring a served order"><source src="./assets/kds-hl-recover.mp4?v=3" type="video/mp4"></video></div><figcaption>A completed order moves to Served, then returns to the board in blue</figcaption></figure></article><div class="kiosk-live-demo kds-live-demo" id="try-demo"><div class="kiosk-live-copy"><span>TRY THE PROTOTYPE / INTERACTIVE DEMO</span><h3>Operate the kitchen display directly</h3><p>A working demo rebuilt from my independent Figma explorations: order, category, and item views; checking items off and sending the checked ones with Batch complete, with fully completed orders moving to served automatically; undoing a completed order; sending served items back for a remake; scheduled orders that move into production automatically; and wait-time color coding with its settings. Orders are simulated, and new ones arrive periodically while intake is on. Some interaction details were added for the demo.</p><a href="./kds-demo/index.html" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese · Not connected to a live system · Tap items to check them off, then send them with Batch complete</small></div><div class="kiosk-live-frame kds-live-frame"><iframe src="./kds-demo/index.html" title="Kitchen display system interactive demo" loading="lazy"></iframe></div></div>'+
  '<div class="kds-design-phase-two"><span>PHASE 02 / FUTURE EXPLORATION, NOT THIS MVP</span><h3>Set preparation batches using capacity and order times</h3><p>Future designs could limit the quantity per batch for each item and split batches when order times are too far apart. The concept uses a maximum of three portions and a ten-minute gap as examples.</p><div class="validation-plan"><span>HOW I WOULD VALIDATE IT / LOW-COST TEST</span><ol><li>Take one store’s historical orders from a single peak period.</li><li>Simulate service under three rules: order by order, unlimited aggregation, and 3 portions / 10-minute splits.</li><li>Compare the longest wait and the number of batches—does splitting reduce batches without noticeably increasing waits?</li><li>Review the simulation with kitchen staff to check the values against real pan capacity and rhythm.</li></ol></div><figure class="kds-shot"><a href="./kds-design-phase-two.png?v=6" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="./kds-design-phase-two.png?v=6" alt="KDS phase-two capacity and time batching concept"></a><figcaption>Concept only: configurable batch capacity and time constraints.</figcaption></figure></div>')+
 section('reflection','06','OUTCOME & REFLECTION','From market-baseline features to understanding kitchen constraints',
  ''+
  '<div class="kds-evidence-columns"><div><h3>What the company project has achieved so far</h3><ul><li>Competitor research, historical evidence, and contextual interviews informed new MVP decisions. Development is progressing toward customer delivery.</li><li>All five information-hierarchy and interaction review recommendations were adopted and reflected in revised UI designs.</li><li>Documented LA PASTA front/back-of-house coordination, production capacity, and timing constraints for further design work.</li></ul></div><div><h3>What still needs validation</h3><ul><li>Whether the new version actually reduces accidental completion or speeds recognition.</li><li>Whether other restaurant types need the same view switching and sequencing controls.</li><li>Whether my independent concepts—ten-minute grouping, item-specific capacity, and batch completion—work in practice (test plan in section 05).</li></ul></div></div>'+
  '<p>Competitor analysis established a market baseline, but could not explain why a particular feature mattered. Combined with historic feedback and field workflows, it became a foundation for actual design tradeoffs rather than a feature checklist.</p>'+
  '<p>Within the company project, I learned to translate research into information hierarchy discussions with another designer. Independently, I explored how <strong>order and item views, production capacity, and fairness of wait times</strong> could form an interactive concept. More restaurant contexts and usage evidence are needed before turning those rules into a product.</p>'+
  '<div class="kds-reflection-bottom"><strong>NEXT QUESTION ↗</strong><p>When kitchen and front-of-house rhythms differ, which steps should be automated, and which decisions should stay with people on site?</p></div>')

 };
 const card=(p,visual)=>`<a class="work-card" href="#/case/${p.id}">${visual(p.visual)}<div class="work-info"><div><h3>${p.title}</h3><p>${({scheduling:'Pilates scheduling platform',kiosk:'Next-generation self-ordering kiosk',kds:'Kitchen display system: team research + personal concept'})[p.id]}<br>${p.type}</p></div><div class="project-number">${p.number} / 03</div></div></a>`;
 function home(projects,visual){return `<section class="identity-hero"><div class="identity-wrap"><div class="identity-caption">PORTFOLIO / 2026</div><div class="identity-title"><span>Yuan</span><figure class="identity-photo"><img src="./yuan-chi-portrait.png" alt="Portrait of Yuan Chi"><i class="corner c1"></i><i class="corner c2"></i><i class="corner c3"></i><i class="corner c4"></i></figure><span>Chi</span></div><div class="identity-details"><p>Product Manager ×<br>Product Designer</p><p>Research / Strategy / Design<br>From insight to working product</p><p>Based in Taiwan<br><a href="mailto:chi861008@gmail.com">chi861008@gmail.com ↗</a></p></div></div></section><section class="intro-portrait wrap" id="about"><div class="intro-copy"><div class="eyebrow">ABOUT ME</div><h2>Hi<span class="orange">.</span></h2><p>I am a product designer moving into product management. I break ambiguous business problems into testable assumptions, then use research, design, and working prototypes to help teams make trade-offs.</p><p>From B2B restaurant systems to building my own scheduling platform, I care about choosing a problem worth solving—and making the solution tangible.</p><a class="intro-link" href="#/about">More about me <span>↗</span></a></div><div class="intro-visual"><img src="./yuan-chi-portrait.png" alt="Portrait of Yuan Chi"><div class="orbit-word">DESIGN · RESEARCH · PRODUCT · BUILD ·</div></div></section><section class="section-space wrap" id="work"><div class="section-head selected-head"><div><div class="eyebrow">SELECTED WORK / 2026</div><h2>Works record<span class="orange">.</span></h2></div><p>Three cases: research that shaped product decisions, a 0→1 build that taught me to re-scope, and team research extended into my own concept.</p></div><div class="work-grid identity-works">${projects.map(x=>card(x,visual)).join('')}</div></section><section class="dark-band"><div class="wrap"><div class="eyebrow">THE WAY I THINK</div><h2>Fall in love with the problem, not the solution.</h2><p>I look for opportunities in evidence, connect user and business needs, and make abstract ideas testable through working products.</p><a href="mailto:chi861008@gmail.com">Let’s connect ↗</a></div></section>`;}
 function about(){return `<div class="wrap"><section class="case-top"><a class="back-link" href="#/">← HOME</a><div class="eyebrow" style="margin-top:75px">THE PERSON BEHIND THE WORK</div><h1>Curious.<br>Thoughtful.<br><span class="orange">Hands-on.</span></h1><p class="case-deck">A product designer with an industrial design background, moving into product management. I care less about screens alone and more about whether a problem is worth solving and which part to solve first—then I validate the answer with research and working prototypes.</p></section></div><section class="section-space wrap" id="about"><div class="about-mini"><div><div class="eyebrow">02 / ABOUT</div><h2>Curious by nature.<br>Builder by choice.</h2></div><div><p>My background spans industrial design, UX research, and digital product design across restaurant POS, self-ordering kiosks, and kitchen display systems. Moving into product management, I frame problems, set priorities, validate at the lowest cost, and build prototypes myself with AI-assisted development when needed.</p><p>I especially enjoy problem framing, finding connections across evidence, storytelling, and making complex interactions understandable.</p><div class="skills"><span class="chip">Product Discovery</span><span class="chip">Prioritization</span><span class="chip">UX Research</span><span class="chip">Product Design</span><span class="chip">Prototyping</span><span class="chip">AI-assisted Development</span></div></div></div></section><section class="dark-band"><div class="wrap"><div class="eyebrow">LET’S CONNECT</div><h2>Have a product problem worth solving?</h2><p>I'd love to connect about product management, product design, and 0→1 opportunities.</p><a href="mailto:chi861008@gmail.com">Say hello ↗</a></div></section>`;}
 const caseLimits={kiosk:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>No end customers were interviewed; needs came from seven merchant managers</b><span>Observe customers in stores after launch and track payment-help requests. “Merchant report” items are my summaries; only the “original participant quote” is verbatim.</span></li><li><b>The prototype was tested with six colleagues; the second iteration was not retested</b><span>Run a second round with real customers, comparing hesitation and errors on set options.</span></li><li><b>The 40-store market scan is an exploratory sample</b><span>Validate the priority store types with sales and adoption data.</span></li><li><b>“Adopted” does not mean shipped</b><span>After launch, track payment completion, task time, and staff interventions.</span></li></ul></details>',scheduling:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>Needs come from a single instructor</b><span>Interview five instructors of different sizes to test whether scheduling time is a shared pain.</span></li><li><b>Only functional tests with sample data; the instructor has not used it yet</b><span>Run one month of real scheduling and measure manual edits and time to final.</span></li><li><b>Time saved, fairness, cancellations, and the 120-lessons target are unvalidated</b><span>Track them as post-adoption metrics.</span></li></ul></details>',kds:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>Field research covered one restaurant and two participants</b><span>Interview kitchens in other formats (fast food, beverages, set meals). “Working context” summaries are synthesized, not verbatim.</span></li><li><b>No post-launch usage data for the new version yet</b><span>Track mistaken-completion recoveries and order-recognition time.</span></li><li><b>My batching rules (3 portions, 10 minutes) are unvalidated</b><span>Simulate them with historical orders first—see section 05.</span></li></ul></details>'};
 function casePage(project,projects,visual){const next=projects[(projects.indexOf(project)+1)%projects.length],id=project.id;
 const snapshotMarkup=`<div class="case-overview-intro case-project-meta"><span>${id==='scheduling'?'Pilates Scheduling System · 2026 · Personal project':id==='kiosk'?'Next-generation Self-ordering Kiosk · Company project':'Kitchen Display System · Team project + personal extension'}</span></div>`+({"scheduling": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>A Pilates instructor spent 2–3 hours a month scheduling, then kept rescheduling after cancellations; letting students self-book increased cancellations.</p></div><div><span>MY ROLE</span><p>Independently defined requirements and scheduling rules, designed the UX/UI, and built a working system that runs inside LINE with AI-assisted development (Next.js, Supabase, LINE LIFF).</p></div><div><span>KEY DECISION</span><p>Replace first-come-first-served with “students submit acceptable times → system drafts the month → instructor finalizes,” keeping her judgment as the last step.</p></div><div><span>OUTCOME & TURN</span><p>With sample data, 10 students × 4 lessons were placed in one run (40/40). The demo showed adoption cost was the real barrier—I learned to validate shared needs before adding features.</p></div></div>", "kiosk": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>Existing KIOSK sales were below expectations. The company planned an integrated ordering-and-payment machine but did not know what the software should change first.</p></div><div><span>MY ROLE</span><p>Consumer-facing flow and UI designer; took part in the market scan, competitor analysis, seven merchant-manager interviews, and a six-person prototype test. I independently proposed the payment-hardware location guide.</p></div><div><span>KEY DECISION</span><p>Prioritize by merchant-reported user problems, weight by competitor prevalence, and gate by feasibility—narrowing 12 directions into priority recommendations instead of a feature list.</p></div><div><span>OUTCOME</span><p>Nine of 12 recommendations were adopted, including my payment-location guide. Payment was the smoothest part of the prototype test; confusion around set options drove four new option layouts.</p></div></div>", "kds": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>An engineer-built KDS demo had to become a deliverable product, but the team did not know how kitchens actually work or what the first release should cover.</p></div><div><span>MY ROLE</span><p><b>Team project:</b> research synthesis, competitor analysis, field interviews, and UI review; another UX designer led the production UI. <b>Personal extension:</b> I independently designed an item view and batching rules, and built an interactive demo.</p></div><div><span>KEY DECISION</span><p>Limit the MVP to two goals: readable preparation information with recoverable mistakes, and support for batch preparation. Sound alerts and store-specific rules come later.</p></div><div><span>OUTCOME</span><p>All five of my UI recommendations were adopted in the revised designs, and the product moved into pre-delivery. The personal extension is unvalidated.</p></div></div>"})[id];
 const deck={scheduling:'I built a working scheduling product—then learned from the instructor’s feedback to rethink what was worth building first.',kiosk:'Using research to decide what a next-generation kiosk should change first—from merchant interviews to an adopted payment-guidance design.',kds:'Research and UI review for a team KDS redesign (all five recommendations adopted), plus my own item-view concept for batch preparation.'}[id];
 const anchors=id==='kds'?['overview','research','user-analysis','opportunity','solutions','reflection']:id==='kiosk'?['overview','research','solutions','validation','reflection']:['overview','research','opportunity','highlights','reflection'];
 const date=id==='kiosk'?'2025.11 — 2026.04':id==='kds'?'2026.06 — 2026.07':project.year;
 const datetime=id==='kiosk'?'2025-11':id==='kds'?'2026-06':'2026';
 return `<div class="wrap"><section class="case-top${id==='kiosk'?' kiosk-cover':id==='kds'?' kds-cover':' scheduling-cover'}"><a href="#/work" class="back-link">← BACK TO SELECTED WORK</a><div class="case-title-row"><h1>${project.title}<span class="orange">.</span></h1><time class="case-cover-date" datetime="${datetime}">${date}</time></div><p class="case-deck">${deck}</p><a class="try-demo-cta" href="#try-demo">Explore interaction <span aria-hidden="true">↓</span></a>${snapshotMarkup}</section><div class="case-layout"><aside class="side-index">${nav[id].map((t,i)=>`<a href="#${anchors[i]}"><b>0${i+1}</b>${t}</a>`).join('')}</aside><article class="case-article">${content[id]()}${id==='kiosk'?'':caseLimits[id]}</article></div><a class="next-case" href="#/case/${next.id}"><div><small>NEXT CASE STUDY →</small><h2>${next.title}</h2></div><span>↗</span></a></div>`;
 }
 return {home,about,casePage};
})();
